def _get_project_dir(ctx) -> str:
    """Resolve .code-expert directory relative to repo root."""
    return os.path.join(_get_repo(ctx), PROJECT_DIR)

caffeinate_hold_body.source:
def hold():
    """Start caffeinate to prevent idle sleep. No-op on non-macOS."""
    global _process
    if _process is not None:
        return
    if platform.system() != "Darwin":
        return
    try:
        _process = subprocess.Popen(
            ["caffeinate", "-i"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        atexit.register(release)
    except FileNotFoundError:
        pass
